export interface Product {
  sku: string;
  name: string;
  category: string;
  categoryCode: string;
  categoryName: string;
  subcategory: string;
  subcategoryCode: string;
  subcategoryName: string;
  range: 'automotive-parts' | 'vehicle-glass' | 'paint-solutions' | 'tools-supplies';
  rangeName: string;
  unit: string;
  description: string;
  brand: string;
  demo?: boolean;
  featured?: boolean;
  inStock?: boolean;
  specs?: Record<string, string>;
  image?: string;
  imageAlt?: string;
  badge?: string;
}

export interface RangeInfo {
  id: 'automotive-parts' | 'vehicle-glass' | 'paint-solutions' | 'tools-supplies';
  name: string;
  description: string;
  itemCount: number;
  highlight: string;
  image: string;
}

export interface SubcategoryInfo {
  slug: string;
  code: string;
  name: string;
  count: number;
}

export interface CategoryInfo {
  slug: string;
  code: string;
  name: string;
  range: 'automotive-parts' | 'vehicle-glass' | 'paint-solutions' | 'tools-supplies';
  description: string;
  productCount: number;
  iconName: string;
  subcategories: SubcategoryInfo[];
}

